contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public {
        require(expiration > block.timestamp);
        require(duration < 10_000 days);

        C.Order memory o;
        o.maker = address(this);
        o.isCall = isCall;
        o.isLong = isLong;
        o.baseAsset = baseAsset;
        o.strike = strike;
        o.premium = premium;
        o.duration = duration;
        o.expiration = expiration;
        o.nonce = nonce;
        o.whitelist = new address[](0);
        o.floorTokens = new address[](0);
        o.erc20Assets = new C.ERC20Asset[](0);
        o.erc721Assets = new C.ERC721Asset[](0);

        bytes32 h = c.hashOrder(o);
        bool cancelledBefore = c.cancelledOrders(h);

        c.cancel(o);

        bool cancelledAfter = c.cancelledOrders(c.hashOrder(o));
        bytes32 oppositeHash = c.hashOppositeOrder(o);
        bool cancelledOpposite = c.cancelledOrders(oppositeHash);

        assert(
            !cancelledBefore &&
            cancelledAfter &&
            !cancelledOpposite &&
            h != oppositeHash
        );
    }

    receive() external payable {}
}

