contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bool isCall, bool isLong, uint256 strike, uint256 premium, uint256 nonce) public payable {
        C.ERC20Asset[] memory ercs = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory nfts = new C.ERC721Asset[](0);
        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.Order memory order = C.Order({
            maker: address(this),
            isCall: isCall,
            isLong: isLong,
            baseAsset: address(0x1234),
            strike: strike,
            premium: premium,
            duration: 100,
            expiration: 99999999999,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: ercs,
            erc721Assets: nfts
        });
        bytes32 h1 = c.hashOrder(order);
        bytes32 h2 = c.hashOrder(order);
        // hashOrder is a deterministic function of the order contents
        assert(h1 == h2);
        c.cancel(order);
        bool cancelled = c.cancelledOrders(h1);
        // cancel by the maker must mark the order hash as cancelled
        assert(cancelled);
        // the opposite-order hash (isLong flipped) is still distinct and not cancelled unless equal
        bytes32 hOpp = c.hashOppositeOrder(order);
        assert(c.cancelledOrders(hOpp) == (hOpp == h1));
    }
}

