contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address makerOther, uint256 strike, uint256 premium) public {
        require(makerOther != address(this), "maker must differ");

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20s = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721s = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: makerOther,
            isCall: true,
            isLong: true,
            baseAsset: address(c),
            strike: strike,
            premium: premium,
            duration: 1 days,
            expiration: block.timestamp + 1 days,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20s,
            erc721Assets: erc721s
        });

        // cancel by a non-maker must revert
        bool revertedNonMaker;
        try c.cancel(order) { revertedNonMaker = false; } catch { revertedNonMaker = true; }

        bytes32 hashBefore = c.hashOrder(order);
        bool cancelledBefore = c.cancelledOrders(uint256(hashBefore));

        // cancel by the maker succeeds
        order.maker = address(this);
        bytes32 hash = c.hashOrder(order);
        c.cancel(order);

        bool cancelledAfter = c.cancelledOrders(uint256(hash));

        assert(
            revertedNonMaker &&
            !cancelledBefore &&
            hash != hashBefore &&
            cancelledAfter
        );
    }

    receive() external payable {}
}

