        uint256 before = c.fee();

        bool reverted;
        if (newFee >= 30) {
            try c.setFee(newFee) { reverted = false; }
            catch { reverted = true; }
        } else {
            c.setFee(newFee);
            reverted = false;
        }

        uint256 afterFee = c.fee();

        if (reverted) {
            assert(newFee >= 30 && afterFee == before);
        } else {
            assert(newFee < 30 && afterFee == newFee);
        }
    }

    receive() external payable {}
}

